con:config.script:
/* Apache POI JARs required in SoapUI bin/ext — see ../SETUP.txt */
import org.apache.poi.ss.usermodel.*
import org.apache.poi.xssf.usermodel.XSSFWorkbook
import java.net.URLEncoder

def pathStr = testRunner.testCase.testSuite.project.path
def projectDir = pathStr ? new File(pathStr).parentFile : new File(System.getProperty("user.dir"))
def excelFile = new File(projectDir, "data/testdata.xlsx")
assert excelFile.exists() : "Excel not found: ${excelFile.absolutePath}. Open project from soapui folder."

def fis = new FileInputStream(excelFile)
def wb = new XSSFWorkbook(fis)
try {
  Sheet sheet = wb.getSheetAt(0)
  Row header = sheet.getRow(0)
  assert header : "No header row"
  def fmt = new DataFormatter()
  def idx = [:]
  header.each { Cell c ->
    if (c != null) {
      def key = fmt.formatCellValue(c).trim().toLowerCase()
      idx[key] = c.columnIndex
    }
  }
  Row row = sheet.getRow(1)
  assert row : "No data row"
  def cell = { String col ->
    Integer i = idx[col.toLowerCase()]
    if (i == null) return null
    Cell c = row.getCell(i)
    return c == null ? "" : fmt.formatCellValue(c).trim()
  }
  def sub = cell("subregion")
  def region = cell("expected_region")
  def sample = cell("sample_country")
  testRunner.testCase.setPropertyValue("subregionRaw", sub ?: "")
  testRunner.testCase.setPropertyValue("expectedRegion", region ?: "")
  testRunner.testCase.setPropertyValue("sampleCountry", sample ?: "")
  def enc = URLEncoder.encode(sub, "UTF-8").replace("+", "%20")
  testRunner.testCase.setPropertyValue("subregionEncoded", enc)
  log.info("Excel -> subregion=${sub}, expectedRegion=${region}, sampleCountry=${sample}")
} finally {
  wb.close()
  fis.close()
}

import groovy.json.JsonSlurper

def rawSub = testRunner.testCase.getPropertyValue("subregionRaw")
def expReg = testRunner.testCase.getPropertyValue("expectedRegion")
def sample = testRunner.testCase.getPropertyValue("sampleCountry")
def responseJson = context.expand('${GET subregion countries#Response}')

assert responseJson : "Empty response"
def data = new JsonSlurper().parseText(responseJson)
assert data instanceof List : "Expected JSON array"
assert data.size() > 0 : "Expected at least one country"

data.each { c ->
  assert c.subregion == rawSub : "subregion mismatch for ${c?.name?.common}: ${c.subregion} vs ${rawSub}"
  if (expReg) {
    assert c.region == expReg : "region mismatch for ${c?.name?.common}"
  }
}

if (sample) {
  def names = data.collect { it?.name?.common }.findAll { it }
  assert names.contains(sample) : "Expected sample country ${sample} in response; got ${names.take(5)}..."
}
log.info("Groovy validation passed (${data.size()} countries).")
